#include <stddef.h>

long long sum(const int values[], size_t count)
{
    long long total = 0;
    for (size_t i = 0; i < count; i++) {
        total += values[i];
    }
    return total;
}

size_t index_of_max(const int values[], size_t count)
{
    size_t best = 0;
    for (size_t i = 1; i < count; i++) {
        if (values[i] > values[best]) best = i;
    }
    return best;
}

void reverse(int values[], size_t count)
{
    if (count < 2) return;
    size_t left = 0;
    size_t right = count - 1;
    while (left < right) {
        int temp = values[left];
        values[left] = values[right];
        values[right] = temp;
        left++;
        right--;
    }
}

size_t count_above(const int values[], size_t count, int limit)
{
    size_t above = 0;
    for (size_t i = 0; i < count; i++) {
        if (values[i] > limit) above++;
    }
    return above;
}

