TEST("sum") { int a[] = {1, 2, 3, 4}; CHECK_EQ(sum(a, 4), 10LL); CHECK_EQ(sum(a, 0), 0LL); int big[] = {2000000000, 2000000000}; CHECK_EQ(sum(big, 2), 4000000000LL); }
TEST("index of the largest") { int a[] = {3, 9, 2, 9, 1}; CHECK_EQ(index_of_max(a, 5), (size_t)1); int b[] = {-5, -2, -9}; CHECK_EQ(index_of_max(b, 3), (size_t)1); int c[] = {7}; CHECK_EQ(index_of_max(c, 1), (size_t)0); }
TEST("reverse an odd length") { int a[] = {1, 2, 3, 4, 5}; reverse(a, 5); CHECK_EQ(a[0], 5); CHECK_EQ(a[1], 4); CHECK_EQ(a[2], 3); CHECK_EQ(a[3], 2); CHECK_EQ(a[4], 1); }
TEST("reverse an even length and tiny arrays") { int a[] = {1, 2, 3, 4}; reverse(a, 4); CHECK_EQ(a[0], 4); CHECK_EQ(a[3], 1); int one[] = {8}; reverse(one, 1); CHECK_EQ(one[0], 8); reverse(one, 0); CHECK_EQ(one[0], 8); }
TEST("count above a limit") { int a[] = {5, 10, 15, 20}; CHECK_EQ(count_above(a, 4, 10), (size_t)2); CHECK_EQ(count_above(a, 4, 100), (size_t)0); CHECK_EQ(count_above(a, 4, -1), (size_t)4); }

